# Pass 211: the three new Blast Drills in construct textures (J, 2026-10-13: "D1 and D2, D3 will be good with
# different construct textures"). Rows: D1 auger, D2 tiered, D3 crystal (shapes from tools/pixel_blast_drill.py).
# Columns: a = construct_brick, b = construct_inner, c = construct_rim (frame 0 of the green animated textures,
# laid on the hard-light faces with box UVs). Cutting edges, core light and the collar slot keep their glow.
# Cameras "Cam D1", "Cam D2", "Cam D3", "Cam all drills". Builds LanternLive\drills_textured.blend, spins them,
# keeps the watcher on. Stills to renders/211_drills_*.png.
import os, math, base64
import bpy, bmesh
import numpy as np
from mathutils import Vector

TEX = {
    "brick": "",
    "inner": "",
    "rim": "",
}

G = 0.25
AX = np.arange(-10, 10, G) + G / 2
AZ = np.arange(0, 40, G) + G / 2
X, Y, Z = np.meshgrid(AX, AX, AZ, indexing="ij")
R = np.hypot(X, Y)
TH = np.arctan2(Y, X)
EMPTY, CORE, BODY, LIGHTP, EDGE, GLOW = range(6)
PAL = {CORE: ((10, 46, 28), 1), BODY: ((24, 120, 66), 4), LIGHTP: ((70, 196, 118), 4),
       EDGE: ((205, 255, 215), 6), GLOW: ((40, 230, 96), 4)}


def collar(part, top=5.0):
    """A hexagonal collar at the base with a glowing slot round it."""
    hexr = np.maximum.reduce([np.abs(X * math.cos(a) + Y * math.sin(a)) for a in (0, math.pi / 3, 2 * math.pi / 3)])
    c = (hexr < 8.6) & (Z < top)
    part[c] = CORE
    slot = c & (np.abs(Z - top * 0.55) < 0.6) & (hexr > 7.7)
    part[slot] = GLOW
    rim = c & (Z > top - 0.6) & (hexr > 7.9)
    part[rim] = EDGE
    return part


def d1():
    part = np.zeros(X.shape, np.int8)
    zt = (Z - 5) / 33.0
    Rz = 8.2 * np.clip(1 - zt, 0, 1) ** 0.9
    inside = (Z >= 5) & (R < Rz)
    part[inside & (R < np.maximum(0.38 * Rz, 0.6))] = CORE
    phase = ((TH / (2 * math.pi)) * 2 + Z / 11.0) % 1
    blade = inside & (phase < 0.24)
    part[blade] = BODY
    part[blade & (phase < 0.05)] = LIGHTP                         # the leading face catches light
    part[blade & (R > Rz - 0.75)] = EDGE                          # the cutting edge glows
    part[(Z >= 5) & (Z < 38.5) & (R < 0.55)] = GLOW               # the light running up the core
    part[(Z >= 37) & (R < 0.8)] = EDGE                            # the tip
    return collar(part)


def d2():
    part = np.zeros(X.shape, np.int8)
    tiers = [(5, 6.5, 8.4), (11.5, 6, 7.0), (17.5, 5.5, 5.6), (23, 5, 4.3), (28, 4.5, 3.0)]
    for i, (z0, h, rad) in enumerate(tiers):
        zz = (Z - z0) / h
        inz = (zz >= 0) & (zz < 1)
        taper = rad * (1 - 0.35 * zz)
        teeth = (((TH / (2 * math.pi)) * (8 + i * 0) + i * 0.5 + zz * 0.35) % 1) < 0.62
        body = inz & (R < taper) & (teeth | (R < taper * 0.72))
        part[body] = BODY
        part[body & (R > taper - 0.6)] = LIGHTP
        part[inz & teeth & (zz > 0.85) & (R > taper * 0.6) & (R < taper)] = EDGE
        gap = (Z >= z0 + h - 0.5) & (Z < z0 + h) & (R < taper * 0.7)
        part[gap] = GLOW                                          # a ring of light between the tiers
    part[(Z >= 5) & (Z < 34) & (R < 1.2)] = CORE
    spike = (Z >= 32.5) & (R < np.clip((37.5 - Z) * 0.32, 0, 2))
    part[spike] = EDGE
    return collar(part)


def d3():
    part = np.zeros(X.shape, np.int8)
    zt = (Z - 5) / 33.0
    hexr = np.maximum.reduce([np.abs(X * math.cos(a) + Y * math.sin(a)) for a in (0, math.pi / 3, 2 * math.pi / 3)])
    Rz = 7.2 * np.clip(1 - zt, 0, 1) ** 1.1
    body = (Z >= 5) & (hexr < Rz)
    part[body] = BODY
    # facet shading: the faces turned to the light are paler
    face = (np.floor((TH + math.pi / 6) / (math.pi / 3)) % 6).astype(int)
    part[body & np.isin(face, (1, 2))] = LIGHTP
    groove = body & (((TH / (2 * math.pi)) * 3 + Z / 9.0) % 1 < 0.07) & (hexr > Rz - 1.0)
    part[groove] = GLOW
    part[groove & (hexr > Rz - 0.5)] = EDGE
    part[body & (hexr < Rz * 0.45)] = CORE
    # shards orbiting the base
    for k in range(6):
        a = k * math.pi / 3 + 0.3
        cx, cy = 7.0 * math.cos(a), 7.0 * math.sin(a)
        d = np.hypot(X - cx, Y - cy)
        shard = (Z >= 5) & (Z < 5 + 7 - k % 2 * 2) & (d < np.clip((12 - k % 2 * 2 - Z) * 0.22, 0, 1.2))
        part[shard] = LIGHTP
        part[shard & (Z > 9.5 - k % 2 * 2)] = EDGE
    return collar(part)


# ================================================================ faces, with the part each face belongs to
def faces(part):
    occ = part > 0
    P = np.pad(occ, 1)
    Q, PID, AXI = [], [], []
    for axis in range(3):
        for sgn in (1, -1):
            sh = np.roll(P, -sgn, axis=axis)[1:-1, 1:-1, 1:-1]
            idx = np.argwhere(occ & ~sh)
            if not len(idx):
                continue
            ctr = np.stack([AX[idx[:, 0]], AX[idx[:, 1]], AZ[idx[:, 2]]], 1)
            n = np.zeros(3); n[axis] = sgn
            a = np.zeros(3); a[(axis + 1) % 3] = 1
            b = np.cross(n, a)
            f0 = ctr + n * G / 2
            Q.append(np.stack([f0 + (a * sa + b * sb) * G / 2 for sa, sb in ((-1, -1), (1, -1), (1, 1), (-1, 1))], 1))
            PID.append(part[idx[:, 0], idx[:, 1], idx[:, 2]]); AXI.append(np.full(len(idx), axis))
    return np.concatenate(Q), np.concatenate(PID), np.concatenate(AXI)


# ================================================================ scene
OUT = os.path.join(FOLDER, "drills_textured.blend")
if bpy.data.filepath:
    try:
        bpy.ops.wm.save_mainfile()
    except Exception:
        pass
old = bpy.data.scenes.get("Drills textured")
if old:
    bpy.data.scenes.remove(old)
scene = bpy.data.scenes.new("Drills textured")
col = scene.collection
scene.render.fps = 24
scene.frame_start, scene.frame_end = 1, 96
win = bpy.context.window
if win:
    win.scene = scene


def label(text, at, size=0.26):
    cu = bpy.data.curves.new("lab " + text, "FONT"); cu.body = text; cu.size = size; cu.align_x = "CENTER"
    o = bpy.data.objects.new("Label " + text, cu); o.location = at; o.rotation_euler = (math.radians(90), 0, 0)
    m = bpy.data.materials.new("lab " + text); m.use_nodes = True
    p = m.node_tree.nodes.get("Principled BSDF")
    p.inputs["Emission Color"].default_value = (0.9, 1, 0.92, 1); p.inputs["Emission Strength"].default_value = 2.0
    cu.materials.append(m)
    col.objects.link(o)


def spin(holder, frames):
    holder.rotation_euler = (0, 0, 0); holder.keyframe_insert("rotation_euler", index=2, frame=1)
    holder.rotation_euler = (0, 0, 2 * math.pi); holder.keyframe_insert("rotation_euler", index=2, frame=frames + 1)
    try:
        for fc in holder.animation_data.action.fcurves:
            for k in fc.keyframe_points:
                k.interpolation = "LINEAR"
            fc.modifiers.new("CYCLES")
    except Exception:
        pass


def plinth(at):
    me = bpy.data.meshes.new("plinth")
    bm = bmesh.new(); bmesh.ops.create_cone(bm, cap_ends=True, segments=32, radius1=0.75, radius2=0.75, depth=0.12); bm.to_mesh(me); bm.free()
    o = bpy.data.objects.new("Plinth", me); o.location = at + Vector((0, 0, -0.06)); col.objects.link(o)
    m = bpy.data.materials.get("plinth") or bpy.data.materials.new("plinth"); m.use_nodes = True
    m.node_tree.nodes.get("Principled BSDF").inputs["Base Color"].default_value = (0.05, 0.055, 0.06, 1)
    me.materials.append(m)


def camera(name, target, loc, lens=50):
    cd = bpy.data.cameras.new(name); cd.lens = lens
    c = bpy.data.objects.new(name, cd); col.objects.link(c)
    c.location = loc
    c.rotation_euler = (target - c.location).to_track_quat("-Z", "Y").to_euler()
    return c


def flat(name, rgb, emit=0.0):
    m = bpy.data.materials.new(name); m.use_nodes = True
    p = m.node_tree.nodes.get("Principled BSDF")
    lin = tuple((c / 255.0) ** 2.2 for c in rgb) + (1,)
    p.inputs["Base Color"].default_value = lin; p.inputs["Roughness"].default_value = 0.3
    if emit:
        p.inputs["Emission Color"].default_value = lin; p.inputs["Emission Strength"].default_value = emit
    return m


def image(key):
    name = "construct_" + key + " (frame 0)"
    im = bpy.data.images.get(name)
    if im is None:
        path = os.path.join(bpy.app.tempdir or FOLDER, f"_ll_{key}.png")
        with open(path, "wb") as fh:
            fh.write(base64.b64decode(TEX[key]))
        im = bpy.data.images.load(path); im.name = name; im.pack()
    return im


def tex_mat(key, tint, emit):
    """A construct texture laid on the hard light, full-bright like the game draws constructs."""
    m = bpy.data.materials.new(f"drill {key} x{tint}"); m.use_nodes = True
    N, L = m.node_tree.nodes, m.node_tree.links
    p = N.get("Principled BSDF")
    t = N.new("ShaderNodeTexImage"); t.image = image(key); t.interpolation = "Closest"
    uv = N.new("ShaderNodeUVMap"); uv.uv_map = "box"; L.new(uv.outputs["UV"], t.inputs["Vector"])
    mul = N.new("ShaderNodeMix"); mul.data_type = "RGBA"; mul.blend_type = "MULTIPLY"
    mul.inputs["Factor"].default_value = 1.0
    L.new(t.outputs["Color"], mul.inputs["A"]); mul.inputs["B"].default_value = (tint, tint, tint, 1)
    L.new(mul.outputs["Result"], p.inputs["Base Color"]); L.new(mul.outputs["Result"], p.inputs["Emission Color"])
    p.inputs["Emission Strength"].default_value = emit; p.inputs["Roughness"].default_value = 0.25
    p.inputs["Coat Weight"].default_value = 0.5
    return m


TILE = 8.0     # model px per texture tile: about five repeats up a drill
LOOKS = [("a", "brick"), ("b", "inner"), ("c", "rim")]
DRILLS = [("D1", "auger", d1), ("D2", "tiered", d2), ("D3", "crystal", d3)]
mats_fixed = {CORE: flat("drill core", (10, 46, 28)), EDGE: flat("drill edge", (205, 255, 215), 6.0),
              GLOW: flat("drill glow", (40, 230, 96), 2.0)}
cams = {}
for row, (dk, dname, fn) in enumerate(DRILLS):
    q, pid, axi = faces(fn())
    verts = q.reshape(-1, 3)
    # box UVs: each face uses the two axes it lies along, so the texture keeps its pixels square
    uvs = np.zeros((len(verts), 2), np.float32)
    ax4 = np.repeat(axi, 4)
    for a in range(3):
        s = ax4 == a
        uvs[s, 0] = verts[s, (a + 1) % 3] / TILE
        uvs[s, 1] = verts[s, (a + 2) % 3] / TILE
    for colm, (lk, tkey) in enumerate(LOOKS):
        code = f"{dk}{lk}"
        me = bpy.data.meshes.new(f"drill {code}")
        me.from_pydata(verts.tolist(), [], np.arange(len(verts)).reshape(-1, 4).tolist())
        uvl = me.uv_layers.new(name="box"); uvl.data.foreach_set("uv", uvs.ravel())
        mats = [mats_fixed[CORE], tex_mat(tkey, 0.8, 0.6), tex_mat(tkey, 1.15, 0.9), mats_fixed[EDGE], mats_fixed[GLOW]]
        for m in mats:
            me.materials.append(m)
        slot = {CORE: 0, BODY: 1, LIGHTP: 2, EDGE: 3, GLOW: 4}
        me.polygons.foreach_set("material_index", np.vectorize(slot.get)(pid).astype(np.int32))
        o = bpy.data.objects.new(f"DT {code} {dname} {tkey}", me); col.objects.link(o)
        o.scale = (1 / 24,) * 3
        at = Vector((row * 9.0 + colm * 2.4, 0, 0))
        holder = bpy.data.objects.new(f"DT holder {code}", None); col.objects.link(holder)
        holder.location = at; o.parent = holder
        spin(holder, 96)
        plinth(at)
        label(f"{code}  {tkey}", at + Vector((0, 0, 1.95)), 0.22)
    cx = row * 9.0 + 2.4
    label(f"{dk}  {dname}", Vector((cx, 0, 2.45)), 0.32)
    cams[dk] = camera(f"Cam {dk}", Vector((cx, 0, 1.2)), Vector((cx, -7.8, 1.9)), 45)
cams["all"] = camera("Cam all drills", Vector((11.4, 0, 1.0)), Vector((11.4, -22.0, 4.5)), 30)

world = bpy.data.worlds.new("Drill World"); world.use_nodes = True
world.node_tree.nodes.get("Background").inputs[0].default_value = (0.02, 0.024, 0.03, 1)
scene.world = world
fl = bpy.data.meshes.new("drill floor")
bm = bmesh.new(); bmesh.ops.create_grid(bm, x_segments=1, y_segments=1, size=30); bm.to_mesh(fl); bm.free()
fo = bpy.data.objects.new("Drill floor", fl); fo.location = (11, 0, -0.12); col.objects.link(fo)
fm = bpy.data.materials.new("drill floor"); fm.use_nodes = True
fm.node_tree.nodes.get("Principled BSDF").inputs["Base Color"].default_value = (0.04, 0.045, 0.05, 1)
fl.materials.append(fm)
key = bpy.data.lights.new("drill key", "AREA"); key.energy = 500; key.size = 20
ko = bpy.data.objects.new("drill key", key); ko.location = (11, -7, 7); ko.rotation_euler = (math.radians(45), 0, 0)
col.objects.link(ko)
scene.render.engine = "BLENDER_EEVEE"
scene.render.resolution_x, scene.render.resolution_y = 1600, 900
try:
    scene.view_settings.view_transform = "Standard"
except Exception:
    pass
scene.camera = cams["all"]
rdir = os.path.join(FOLDER, "renders"); os.makedirs(rdir, exist_ok=True)
if not os.environ.get("LL_NO_RENDER"):
    for k, c in cams.items():
        scene.camera = c; scene.frame_set(1)
        scene.render.filepath = os.path.join(rdir, f"211_drills_{k}.png")
        bpy.ops.render.render(write_still=True, scene=scene.name)
    scene.camera = cams["all"]
scene.frame_set(1)
for sc in list(bpy.data.scenes):
    if sc != scene:
        bpy.data.scenes.remove(sc)
try:
    bpy.ops.outliner.orphans_purge(do_recursive=True)
except Exception:
    pass
bpy.ops.wm.save_as_mainfile(filepath=OUT)


def _after():
    try:
        sc = bpy.context.scene
        if hasattr(sc, "lantern_live_watch") and not sc.lantern_live_watch:
            sc.lantern_live_watch = True
        for w in bpy.context.window_manager.windows:
            for a in w.screen.areas:
                if a.type == "VIEW_3D":
                    for sp in a.spaces:
                        if sp.type == "VIEW_3D":
                            sp.region_3d.view_perspective = "CAMERA"; sp.shading.type = "RENDERED"
                    with bpy.context.temp_override(window=w, area=a):
                        if not bpy.context.screen.is_animation_playing:
                            bpy.ops.screen.animation_play()
                    return None
    except Exception as e:
        print("after:", e)
    return None


bpy.app.timers.register(_after, first_interval=4.0)
print("saved", OUT)
